void StudioMain::choosePlugin(){
    if(!canEdit()){status(juce::String::fromUTF8("Dừng phát/thu trước khi nạp VST3."));return;}
    auto start=juce::File::getSpecialLocation(juce::File::globalApplicationsDirectory).getChildFile("Common Files/VST3");
    const auto previous=settings()->getValue("vst3Directory");
    if(previous.isNotEmpty()&&juce::File(previous).isDirectory())start=juce::File(previous);
    if(!start.isDirectory())start=juce::File::getSpecialLocation(juce::File::globalApplicationsDirectory);
    chooser=std::make_unique<juce::FileChooser>(juce::String::fromUTF8("Chọn plugin .vst3 hoặc thư mục chứa plugin"),start,"*",false);
    juce::Component::SafePointer<StudioMain> safe(this);
    chooser->launchAsync(juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::canSelectDirectories,[safe](const juce::FileChooser& c){
        if(!safe||c.getResult()==juce::File{}||!safe->canEdit())return;
        const auto selected=c.getResult();
        safe->settings()->setValue("vst3Directory",(selected.hasFileExtension("vst3")?selected.getParentDirectory():selected).getFullPathName());
        safe->status(juce::String::fromUTF8("Đang nhận dạng VST3…"));
        auto descriptions=std::make_shared<juce::OwnedArray<juce::PluginDescription>>();
        for(int i=0;i<safe->engine.pluginFormats.getNumFormats();++i){
            auto* format=safe->engine.pluginFormats.getFormat(i);
            if(format->getName()!="VST3")continue;
            if(selected.hasFileExtension("vst3"))format->findAllTypesForFile(*descriptions,selected.getFullPathName());
            else if(selected.isDirectory()){
                juce::FileSearchPath paths;paths.add(selected);
                for(const auto& candidate:format->searchPathsForPlugins(paths,true,false))
                    format->findAllTypesForFile(*descriptions,candidate);
            }
        }
        if(descriptions->isEmpty()){
            safe->status(juce::String::fromUTF8("Không tìm thấy VST3. Kiểm tra C:\\Program Files\\Common Files\\VST3 hoặc cài thành phần VST3 64-bit của Auto-Tune."));return;
        }
        auto load=[safe,descriptions](int choice){
            if(!safe||!safe->canEdit()||!juce::isPositiveAndBelow(choice-1,descriptions->size()))return;
            const auto& description=*(*descriptions)[choice-1];
            safe->setBusy(true,juce::String::fromUTF8("Đang nạp ")+description.name+juce::String::fromUTF8("…"));
            safe->engine.pluginFormats.createPluginInstanceAsync(description,safe->engine.rate(),safe->engine.blockSize(),[safe](std::unique_ptr<juce::AudioPluginInstance> instance,const juce::String& error){
                if(!safe)return;
                safe->setBusy(false);
                if(!instance){safe->status(error);return;}
                safe->pluginWindow.reset();
                auto result=safe->engine.installPlugin(std::move(instance));
                if(result.wasOk())safe->setupRestoreFailed=false;
                safe->pluginLabel.setText(safe->engine.pluginName(),juce::dontSendNotification);
                safe->save();
                safe->status(result.wasOk()?juce::String::fromUTF8("Đã nạp VST3 · Độ trễ plugin được bù với beat."):result.getErrorMessage());
            });
        };
        if(descriptions->size()==1){load(1);return;}
        juce::PopupMenu menu;
        for(int i=0;i<descriptions->size();++i)menu.addItem(i+1,(*descriptions)[i]->name+" ("+(*descriptions)[i]->manufacturerName+")");
        menu.showMenuAsync(juce::PopupMenu::Options{},load);
    });
}
void StudioMain::showPlugin(){if(busy)return;if(pluginWindow){pluginWindow->setVisible(true);pluginWindow->toFront(true);return;}auto* plugin=engine.pluginInstance();if(!plugin){status(juce::String::fromUTF8("Chưa có VST3. Vocal FX tích hợp vẫn hoạt động."));return;}auto* editor=plugin->createEditorIfNeeded();if(!editor)editor=new juce::GenericAudioProcessorEditor(*plugin);pluginWindow=std::make_unique<FloatingWindow>(plugin->getName(),editor,true);}
void StudioMain::selectTrack(int index){if(index!=selected){pitchAnalysis.reset();toneStatus={};}selected=juce::isPositiveAndBelow(index,static_cast<int>(engine.getTracks().size()))?index:-1;refreshInspector();canvas.repaint();}
void StudioMain::refreshInspector(){const bool valid=juce::isPositiveAndBelow(selected,static_cast<int>(engine.getTracks().size()));trackGain.setEnabled(valid);trackPan.setEnabled(valid);mute.setEnabled(valid);solo.setEnabled(valid);vocalType.setEnabled(valid&&canEdit());if(!valid){trackTitle.setText("INPUT / VOCAL",juce::dontSendNotification);trackInfo.setText(juce::String::fromUTF8("Chọn một track để chỉnh gain, pan, mute và solo."),juce::dontSendNotification);return;}const auto& t=*engine.getTracks()[static_cast<std::size_t>(selected)];trackTitle.setText(t.name,juce::dontSendNotification);trackGain.setValue(t.gainDb.load(),juce::dontSendNotification);trackPan.setValue(t.pan.load(),juce::dontSendNotification);mute.setToggleState(t.mute.load(),juce::dontSendNotification);solo.setToggleState(t.solo.load(),juce::dontSendNotification);vocalType.setToggleState(t.vocal,juce::dontSendNotification);trackInfo.setText(juce::String::fromUTF8("Bắt đầu: ")+clockText(t.start)+juce::String::fromUTF8("\nĐộ dài: ")+clockText(t.duration())+"\n"+juce::String(t.sourceRate/1000,1)+juce::String::fromUTF8(" kHz · ")+juce::String(t.audio.getNumChannels())+juce::String::fromUTF8(" ch\nKéo thân clip để di chuyển; kéo mép để cắt."),juce::dontSendNotification);}
void StudioMain::refreshTracks(){canvas.setSize(juce::jmax(1,viewport.getMaximumVisibleWidth()),juce::jmax(viewport.getHeight(),TrackCanvas::rulerHeight+static_cast<int>(engine.getTracks().size())*TrackCanvas::rowHeight+25));const double visible=juce::jmax(1.0,(canvas.getWidth()-TrackCanvas::headerWidth)/canvas.zoom);horizontal.setRangeLimits(0,juce::jmax(30.0,engine.duration()+engine.effectTailSeconds()+2.0));horizontal.setCurrentRange(canvas.scrollSeconds,visible,juce::dontSendNotification);canvas.repaint();}
void StudioMain::rememberEdit(int index,double bs,double bi,double bo,double as,double ai,double ao){if(bs==as&&bi==ai&&bo==ao)return;undo.push_back({index,bs,bi,bo,as,ai,ao});if(undo.size()>100)undo.pop_front();redo.clear();save();}
void StudioMain::undoEdit(bool forward){if(!canEdit())return;auto& from=forward?redo:undo;auto& to=forward?undo:redo;if(from.empty())return;const auto edit=from.back();from.pop_back();if(!juce::isPositiveAndBelow(edit.track,static_cast<int>(engine.getTracks().size())))return;engine.withAudioStopped([&]{auto& t=*engine.getTracks()[static_cast<std::size_t>(edit.track)];t.start=forward?edit.afterStart:edit.beforeStart;t.trimIn=forward?edit.afterIn:edit.beforeIn;t.trimOut=forward?edit.afterOut:edit.beforeOut;});to.push_back(edit);selectTrack(edit.track);refreshTracks();save();}
void StudioMain::timerCallback(){if(calibrating&&calibrationDeadline>0&&juce::Time::getMillisecondCounterHiRes()>=calibrationDeadline&&!busy){calibrationDeadline=0;stop();}
    shownInput=juce::jmax(engine.inputPeak.load(),shownInput*.88f);shownOutput=juce::jmax(engine.outputPeak.load(),shownOutput*.88f);positionLabel.setText(clockText(engine.position()),juce::dontSendNotification);deviceLabel.setText(engine.deviceSummary(),juce::dontSendNotification);playButton.setButtonText(engine.isPlaying()?juce::String::fromUTF8("Tạm dừng"):juce::String::fromUTF8("Phát"));recordButton.setColour(juce::TextButton::buttonColourId,engine.isRecording()?red:juce::Colour(0xff69323d));recordButton.setButtonText(engine.isRecording()?juce::String::fromUTF8("DỪNG THU"):"THU");recordButton.setEnabled(!busy);playButton.setEnabled(!busy);importButton.setEnabled(!busy&&!engine.isRecording());openButton.setEnabled(!busy&&!engine.isRecording());newButton.setEnabled(!busy&&!engine.isRecording());deviceButton.setEnabled(!busy&&!engine.isRecording()&&!engine.isPlaying());pluginButton.setEnabled(canEdit());removePluginButton.setEnabled(canEdit()&&engine.pluginInstance()!=nullptr);editorButton.setEnabled(!busy&&engine.pluginInstance()!=nullptr);vocalType.setEnabled(selected>=0&&canEdit());undoButton.setEnabled(canEdit()&&!undo.empty());exportButton.setEnabled(exporting||canEdit());exportButton.setButtonText(exporting?juce::String::fromUTF8("Hủy xuất ")+juce::String(static_cast<int>(exportProgress.load()*100))+"%":juce::String::fromUTF8("Xuất WAV"));
    toolsButton.setEnabled(!busy);if(toolsWindow&&toolsWindow->isVisible()&&!busy){syncKnobs();refreshTracks();}
    saveButton.setEnabled(!busy);presetSelect.setEnabled(!busy);bypass.setEnabled(!busy);monitoring.setEnabled(!busy);for(auto& k:knobs)k->slider.setEnabled(!busy);trackGain.setEnabled(!busy&&selected>=0);trackPan.setEnabled(!busy&&selected>=0);mute.setEnabled(!busy&&selected>=0);solo.setEnabled(!busy&&selected>=0);
    if(deviceWindow)deviceWindow->getContentComponent()->setEnabled(!engine.isRecording()&&!engine.isPlaying()&&!busy);
    const auto names=engine.inputNames();if(names.size()!=inputSelect.getNumItems()||(names.size()>0&&inputSelect.getItemText(0)!=names[0])){inputSelect.clear(juce::dontSendNotification);inputSelect.addItemList(names,1);inputSelect.setSelectedItemIndex(juce::jlimit(0,juce::jmax(0,names.size()-1),engine.inputChannel.load()),juce::sendNotificationSync);inputSelect.setTextWhenNothingSelected(juce::String::fromUTF8("Chọn ngõ vào micro"));}
    if(engine.isPlaying()){const double visible=(canvas.getWidth()-TrackCanvas::headerWidth)/canvas.zoom;if(engine.position()>canvas.scrollSeconds+visible-1||engine.position()<canvas.scrollSeconds){canvas.scrollSeconds=juce::jmax(0.0,engine.position()-visible*.2);horizontal.setCurrentRangeStart(canvas.scrollSeconds,juce::dontSendNotification);}}
    if(!busy&&engine.recordingFault.load()!=0&&engine.hasUnfinishedTake()){finishTake();}
    if(++autosaveTicks>=150){autosaveTicks=0;if(!busy)save();}
    if(!busy&&!engine.isRecording()&&!importQueue.empty()){const auto request=importQueue.front();importQueue.pop_front();importAudio(request.first,request.second);}
    canvas.repaint();repaint();}
bool StudioMain::keyPressed(const juce::KeyPress& key){if(busy)return false;if(key==juce::KeyPress::spaceKey){if(engine.isRecording())stop();else if(engine.isPlaying())engine.stop();else{auto r=engine.play();if(r.failed())status(r.getErrorMessage());}return true;}if(key.getModifiers().isCommandDown()&&key.getKeyCode()=='S'){save();status(juce::String::fromUTF8("Đã lưu phiên thu."));return true;}if(key.getModifiers().isCommandDown()&&key.getKeyCode()=='Z'){undoEdit(key.getModifiers().isShiftDown());return true;}if(key.getKeyCode()=='R'&&!key.getModifiers().isCommandDown()){record();return true;}if(key.getKeyCode()==juce::KeyPress::deleteKey&&selected>=0&&canEdit()){engine.removeTrack(selected);undo.clear();redo.clear();selectTrack(-1);refreshTracks();save();status(juce::String::fromUTF8("Đã bỏ track khỏi phiên thu. File âm thanh gốc được giữ nguyên."));return true;}return false;}
bool StudioMain::isInterestedInFileDrag(const juce::StringArray& files){for(const auto& name:files)if(juce::File(name).hasFileExtension("wav;mp3;flac;aiff;aif;vocalstudio"))return true;return false;}
void StudioMain::filesDropped(const juce::StringArray& files,int,int){for(const auto& name:files){const juce::File file(name);if(file.hasFileExtension("vocalstudio")){status(juce::String::fromUTF8("Dùng nút Mở để nạp phiên .vocalstudio."));continue;}importAudio(file,false);}}
void StudioMain::prepareToClose(std::function<void()> done){if(busy){status(juce::String::fromUTF8("Đợi tác vụ hoàn tất trước khi đóng."));return;}if(closing)return;cancelAutoEq();closing=true;if(engine.isRecording()||engine.hasUnfinishedTake()){finishTake([this,done]{save();persistDeviceSettings();done();});}else{engine.stop();save();persistDeviceSettings();done();}}
void StudioMain::loadDemo(){engine.createDemo();projectFile=engine.session().getChildFile("Demo.vocalstudio");selectTrack(1);refreshTracks();status(juce::String::fromUTF8("DEMO KIỂM THỬ · Sóng tổng hợp để xem giao diện, không phải giọng hát đã xử lý."));}

void StudioMain::showVocalTools(){if(toolsWindow){toolsWindow->setVisible(true);toolsWindow->toFront(true);return;}toolsWindow=std::make_unique<FloatingWindow>(juce::String::fromUTF8("Vocal Studio · Vang, Tone và Chỉnh phô"),createVocalTools(*this),true);toolsWindow->setResizeLimits(940,700,1600,1100);}
void StudioMain::analyseSelected(){if(!canEdit()||selected<0){status(juce::String::fromUTF8("Dừng phát/thu và chọn track cần dò."));return;}const int index=selected;const bool isVocal=engine.getTracks()[static_cast<std::size_t>(index)]->vocal;setBusy(true,juce::String::fromUTF8("Đang dò cao độ và giọng trưởng/thứ…"));cancelExport.store(false);exportProgress.store(0);toneStatus=juce::String::fromUTF8("Đang phân tích track đã chọn…");auto analysis=std::make_shared<vocal::PitchAnalysis>();auto result=std::make_shared<juce::Result>(juce::Result::ok());juce::Component::SafePointer<StudioMain> safe(this);
    runJob([this,index,analysis,result]{*result=engine.analyseTrack(index,*analysis,cancelExport,exportProgress);},[safe,analysis,result,isVocal]{if(!safe)return;if(result->failed()){if(!isVocal)safe->engine.setSongKey(-1,false,juce::String::fromUTF8("Dò bài bị hủy/lỗi"));safe->toneStatus=result->getErrorMessage();safe->status(safe->toneStatus);return;}safe->pitchAnalysis=analysis;if(!isVocal)safe->engine.setSongKey(analysis->keyConfidence>=.5?analysis->tonic:-1,analysis->minor,safe->engine.getTracks()[static_cast<std::size_t>(safe->selected)]->name);juce::String summary;if(analysis->tonic>=0)summary=juce::String::fromUTF8("Tone gợi ý: ")+juce::String(vocal::noteName(60+analysis->tonic))+(analysis->minor?" minor":" major")+juce::String::fromUTF8(" · Điểm phù hợp ")+juce::String(static_cast<int>(analysis->keyConfidence*100))+"/100"+juce::String::fromUTF8(" · Khả năng khác: ")+juce::String(analysis->alternative);else summary=juce::String::fromUTF8("Chưa đủ nốt để suy ra giọng trưởng/thứ. Chọn tone bằng tay hoặc dùng Chromatic.");if(isVocal&&analysis->medianHz>0){const double midi=69+12*std::log2(analysis->medianHz/440);summary+=juce::String::fromUTF8("\nNốt giữa: ")+juce::String(vocal::noteName(midi))+juce::String(static_cast<int>(std::llround(midi))/12-1)+" · "+juce::String(analysis->medianHz,1)+" Hz"+juce::String::fromUTF8(" · Có giọng ")+juce::String(analysis->voicedFraction*100,0)+"%";}summary+=juce::String::fromUTF8("\nMẫu gần clip: ")+juce::String(analysis->clippedFraction*100,2)+juce::String::fromUTF8("%. Kết quả dò là gợi ý; hãy đối chiếu khi nghe.");safe->toneStatus=summary;safe->status(juce::String::fromUTF8("Đã dò tone. Xem kết quả trong Vang / Tone / Chỉnh phô."));});
}
void StudioMain::applyPitch(const vocal::PitchOptions& options){if(!canEdit()||selected<0)return;if(options.semitones==0&&options.cents==0&&options.correction<=0&&!options.repairLightClip){toneStatus=juce::String::fromUTF8("Chọn nâng/hạ tone, bật chỉnh phô hoặc làm dịu clip trước khi áp dụng.");return;}const int index=selected;setBusy(true,juce::String::fromUTF8("Đang tạo bản chỉnh tone, giữ tempo và WAV gốc…"));cancelExport.store(false);exportProgress.store(0);toneStatus=juce::String::fromUTF8("Đang xử lý vào file mới. Hủy để giữ nguyên bản đang dùng.");struct Render {juce::Result result=juce::Result::ok();std::unique_ptr<StudioTrack> track;};auto render=std::make_shared<Render>();juce::Component::SafePointer<StudioMain> safe(this);
    runJob([this,index,options,render]{render->result=engine.renderPitchTrack(index,options,render->track,cancelExport,exportProgress);},[safe,index,render]{if(!safe)return;if(render->result.failed()||!render->track){safe->toneStatus=render->result.getErrorMessage();safe->status(safe->toneStatus);return;}safe->engine.replaceTrack(index,std::move(render->track));safe->undo.clear();safe->redo.clear();safe->pitchAnalysis.reset();safe->selectTrack(index);safe->refreshTracks();safe->save();safe->toneStatus=juce::String::fromUTF8("Đã áp dụng lên bản sao. WAV gốc vẫn còn; dùng Về bản gốc để phục hồi.\nDò lại nếu muốn kiểm tra cao độ sau xử lý. Mỗi lần nâng/hạ là tương đối với bản đang chọn.");safe->status(juce::String::fromUTF8("Đã xử lý tone / chỉnh phô. Nhấn Phát để nghe."));if(!safe->engine.getTracks()[static_cast<std::size_t>(index)]->vocal&&safe->engine.toneLink.enabled)safe->analyseSelected();});
}
void StudioMain::restorePitch(){if(!canEdit()||selected<0)return;const int index=selected;const auto& track=*engine.getTracks()[static_cast<std::size_t>(index)];if(track.file==track.originalFile){toneStatus=juce::String::fromUTF8("Track đang dùng file gốc.");return;}setBusy(true,juce::String::fromUTF8("Đang mở lại WAV gốc…"));struct Restore {juce::Result result=juce::Result::ok();std::unique_ptr<StudioTrack> track;};auto restore=std::make_shared<Restore>();juce::Component::SafePointer<StudioMain> safe(this);runJob([this,index,restore]{restore->result=engine.restoreOriginalTrack(index,restore->track);},[safe,index,restore]{if(!safe)return;if(restore->result.failed()){safe->toneStatus=restore->result.getErrorMessage();return;}safe->engine.replaceTrack(index,std::move(restore->track));safe->undo.clear();safe->redo.clear();safe->pitchAnalysis.reset();safe->selectTrack(index);safe->refreshTracks();safe->save();safe->toneStatus=juce::String::fromUTF8("Đã quay về WAV gốc. File xử lý vẫn được giữ trong thư mục Audio.");safe->status(safe->toneStatus);});}
void StudioMain::saveToolScreenshots(const juce::File& folder){{std::unique_ptr<juce::Component> fix(createTuneFixPanel(*this));auto image=fix->createComponentSnapshot(fix->getLocalBounds());auto stream=folder.getChildFile("VocalStudio-FixAutoTune.jpg").createOutputStream();if(stream){juce::JPEGImageFormat format;format.setQuality(.9f);format.writeImageToStream(image,*stream);}}{std::unique_ptr<juce::Component> polish(createPolishPanel(*this));auto image=polish->createComponentSnapshot(polish->getLocalBounds());auto stream=folder.getChildFile("VocalStudio-Polish.jpg").createOutputStream();if(stream){juce::JPEGImageFormat format;format.setQuality(.9f);format.writeImageToStream(image,*stream);}}std::unique_ptr<juce::Component> autoEq(createAutoEqPanel(*this));auto image=autoEq->createComponentSnapshot(autoEq->getLocalBounds());{auto stream=folder.getChildFile("VocalStudio-AutoEQ.jpg").createOutputStream();if(stream){juce::JPEGImageFormat format;format.setQuality(.9f);format.writeImageToStream(image,*stream);}}showVocalTools();if(selected>=0){auto analysis=std::make_shared<vocal::PitchAnalysis>();std::atomic<bool> cancelled{false};std::atomic<float> progress{0};if(engine.analyseTrack(selected,*analysis,cancelled,progress).wasOk()){pitchAnalysis=analysis;toneStatus=juce::String::fromUTF8("DEMO kiểm thử sóng tổng hợp. Dò cao độ được thực hiện bằng engine thật; không phải giọng hát.");}}auto* tabs=dynamic_cast<juce::TabbedComponent*>(toolsWindow->getContentComponent());if(!tabs)return;refreshVocalTools(*tabs);const char* shotNames[]={"VocalStudio-FX.jpg","VocalStudio-Tone.jpg","VocalStudio-VoiceFit.jpg","VocalStudio-Antares.jpg"};for(int i=0;i<4;++i){tabs->setCurrentTabIndex(i);auto image=tabs->createComponentSnapshot(tabs->getLocalBounds());auto stream=folder.getChildFile(shotNames[i]).createOutputStream();if(stream){juce::JPEGImageFormat format;format.setQuality(.9f);format.writeImageToStream(image,*stream);}}}

void StudioMain::showQuickMode(bool enabled){if(enabled){if(!karaoke){karaoke=std::make_unique<KaraokePage>(*this);addChildComponent(karaoke.get());}karaoke->setBounds(getLocalBounds());karaoke->setVisible(true);karaoke->toFront(false);engine.liveMode=true;}else{engine.liveMode=false;if(karaoke)karaoke->setVisible(false);syncKnobs();}}
void StudioMain::startBrowserProbe(){if(auto* page=dynamic_cast<KaraokePage*>(karaoke.get()))page->probe();}
std::uint64_t StudioMain::browserCaptured() const{if(auto* page=dynamic_cast<KaraokePage*>(karaoke.get()))return page->captured();return 0;}

float StudioMain::browserPeak() const{if(auto* page=dynamic_cast<KaraokePage*>(karaoke.get()))return page->capturedPeak();return 0;}

extern juce::Component* createAutoEqPanel(StudioMain&);
void StudioMain::showAutoEq(){if(eqWindow){eqWindow->setVisible(true);eqWindow->toFront(true);return;}eqWindow=std::make_unique<FloatingWindow>(juce::String::fromUTF8("Hát một bài · Cân EQ giọng tôi"),createAutoEqPanel(*this),true);static_cast<FloatingWindow*>(eqWindow.get())->closed=[this]{if(eqRecording){eqRecording=false;record();}cancelAutoEq();};}

void StudioMain::pauseMusicForEq(){if(auto* page=dynamic_cast<KaraokePage*>(karaoke.get()))page->pauseMusic();}

void StudioMain::showPolish(){if(polishWindow){polishWindow->setVisible(true);polishWindow->toFront(true);return;}polishWindow=std::make_unique<FloatingWindow>(juce::String::fromUTF8("Vocal studio · Cân giọng / Dịu gắt / Vang chìm"),createPolishPanel(*this),true);polishWindow->setResizeLimits(760,570,1800,1200);}
void StudioMain::exportVocal(){if(isBusy()||engine.isRecording())return;int index=selected;if(index<0||index>=static_cast<int>(engine.getTracks().size())||!engine.getTracks()[static_cast<std::size_t>(index)]->vocal){status(juce::String::fromUTF8("Thu micro hoặc chọn một track vocal trong Studio trước khi xuất giọng có FX."));return;}engine.stop();pauseMusicForEq();const auto source=engine.getTracks()[static_cast<std::size_t>(index)]->originalFile;chooser=std::make_unique<juce::FileChooser>(juce::String::fromUTF8("Xuất riêng vocal đã xử lý · WAV stereo 24-bit"),engine.session().getChildFile("Vocal_Studio.wav"),"*.wav");juce::Component::SafePointer<StudioMain> safe(this);chooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting,[safe,index,source](const juce::FileChooser& c){if(!safe||c.getResult()==juce::File{})return;if(!safe->canEdit()||!juce::isPositiveAndBelow(index,static_cast<int>(safe->engine.getTracks().size()))||safe->engine.getTracks()[static_cast<std::size_t>(index)]->originalFile!=source){safe->status(juce::String::fromUTF8("Nguồn vocal đã đổi; chọn lại trước khi xuất."));return;}safe->save();safe->setBusy(true,juce::String::fromUTF8("Đang xuất vocal với EQ/Antares/vang hiện tại, giữ WAV micro gốc…"));safe->exporting=true;safe->cancelExport=false;safe->exportProgress=0;const auto output=c.getResult().withFileExtension("wav");auto result=std::make_shared<juce::Result>(juce::Result::ok());safe->runJob([safe,index,output,result]{if(safe)*result=safe->engine.exportMix(output,safe->cancelExport,safe->exportProgress,index);},[safe,result,output]{if(safe)safe->status(result->wasOk()?juce::String::fromUTF8("Đã xuất riêng vocal có FX: ")+output.getFullPathName():result->getErrorMessage());});});}

void StudioMain::showTuneFix(){if(tuneFixWindow){tuneFixWindow->setVisible(true);tuneFixWindow->toFront(true);return;}tuneFixWindow=std::make_unique<FloatingWindow>(juce::String::fromUTF8("Fix méo Auto-Tune"),createTuneFixPanel(*this),true);tuneFixWindow->setResizeLimits(800,560,1800,1200);}
